const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define geometry - area east of Nile River in Cairo
  const geometry = ee.Geometry.Polygon([
    [31.25, 30.05], [31.35, 30.05], [31.35, 30.10], [31.25, 30.10], [31.25, 30.05]
  ]);

  // Function to mask clouds for Landsat
  function maskLandsatClouds(image) {
    const qa = image.select('QA_PIXEL');
    const cloudBitMask = 1 << 3;
    const cloudShadowBitMask = 1 << 4;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cloudShadowBitMask).eq(0));
    return image.updateMask(mask);
  }

  // Function to calculate NDBI for built-up area
  function calculateNDBI(image) {
    const ndbi = image.normalizedDifference(['SR_B5', 'SR_B4']).rename('NDBI'); // For Landsat 5
    return image.addBands(ndbi);
  }

  function calculateNDBI_L8(image) {
    const ndbi = image.normalizedDifference(['SR_B6', 'SR_B5']).rename('NDBI'); // For Landsat 8
    return image.addBands(ndbi);
  }

  // Process 1984 data (Landsat 5)
  const col1984 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterBounds(geometry)
    .filterDate('1984-07-01', '1984-07-31')
    .map(maskLandsatClouds)
    .map(calculateNDBI);

  // Process 2019 data (Landsat 8)  
  const col2019 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(geometry)
    .filterDate('2019-09-01', '2019-09-30')
    .map(maskLandsatClouds)
    .map(calculateNDBI_L8);

  // Check collection sizes
  const size1984 = col1984.size().getInfo();
  const size2019 = col2019.size().getInfo();

  print(`1984 Images: ${size1984}, 2019 Images: ${size2019}`);

  if (size1984 === 0 || size2019 === 0) {
    print("<answer>C1</answer>");
    return;
  }

  // Get median composites
  const img1984 = col1984.median().select('NDBI');
  const img2019 = col2019.median().select('NDBI');

  // Calculate built-up area (NDBI > 0 indicates built-up)
  const builtup1984 = img1984.gt(0);
  const builtup2019 = img2019.gt(0);

  // Count built-up pixels
  const count1984 = builtup1984.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geometry,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDBI');

  const count2019 = builtup2019.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geometry,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDBI');

  const pixelCount1984 = count1984.getInfo();
  const pixelCount2019 = count2019.getInfo();

  print(`1984 Built-up Pixels: ${pixelCount1984}`);
  print(`2019 Built-up Pixels: ${pixelCount2019}`);

  if (pixelCount1984 === 0 || pixelCount2019 === 0) {
    print("<answer>C2</answer>");
    return;
  }

  // Calculate percentage change
  const changePercent = ((pixelCount2019 - pixelCount1984) / pixelCount1984 * 100);

  print(`Change: ${changePercent.toFixed(1)}%`);

  // Validate result
  if (changePercent === null || !isFinite(changePercent) || changePercent < -100 || changePercent > 10000) {
    print("<answer>C3</answer>");
  } else if (changePercent > 0) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
